/**
 * generated by stackra gen from services/commerce/stackra.manifest.json (its catalogue, inventory,
 * orders and loyalty modules, and the merged @acme/loyalty-kit and @acme/access-log modules) — do
 * not edit
 * Purpose: `#stackra/clients/commerce`: every commerce action, query, permission set, widget,
 *          event, refusal, enum, shape and module the areas the console hosts may reach, each as a
 *          named class under its producer's class name (`OrderKpisQuery`, `CreateOrderAction`,
 *          `OrderPaid`, `OrdersModule`), imported by name; no namespace object to walk. Consumed
 *          services are inferred from the `#stackra/clients/<service>` subpaths the app imports.
 * Boundary: descriptors and shapes only; @stackra/clients performs the call (Idempotency-Key,
 *           session, X-Tenant, envelope, the declared confirmation and texts). A public-area
 *           descriptor never appears here: gen fails when an app-area member references one.
 *           Action and query keys carry their major (`@1`), integration events their version;
 *           texts are the producer's derived keys (`<module>::actions.<key>.<part>`,
 *           `<module>::errors.<code>.message`). A query's `invalidateOn` is its declared cache
 *           invalidation, so a client refetches it when one of those events is broadcast.
 * Runtime: browser
 */
import {
  actionRef,
  clientModule,
  eventRef,
  permissionRefs,
  queryRef,
  refusalRef,
  remoteShape,
  widgetRef,
} from "@stackra/clients";
import { HttpMethod, Tone } from "@stackra/contracts";
import { Risk } from "@stackra/iam";
